import argparse
import datetime as dt
import json
import pathlib
import re
import subprocess
import sys
from collections import defaultdict
from typing import Any, Iterable


PATH_DETECTORS = {
    "environment-file": re.compile(r"(?:^|/)\.env(?:\..+)?$", re.I),
    "credential-name": re.compile(r"(?:^|/|[-_.])(secret|secrets|credential|credentials)(?:$|/|[-_.])", re.I),
    "private-key-name": re.compile(r"(?:^|/)(id_rsa|id_dsa|id_ecdsa|id_ed25519)$|\.(key|pem|p12|pfx|keystore|jks)$", re.I),
}

CONTENT_DETECTORS = {
    "private-key-material": r"-----BEGIN ([A-Z0-9 ]+ )?PRIVATE KEY-----",
    "credential-assignment": r"(api[_-]?key|access[_-]?token|auth[_-]?token|client[_-]?secret|password|passwd)[[:space:]]*[:=]",
    "github-token": r"gh[pousr]_[A-Za-z0-9_]{20,}",
    "credential-url": r"://[^/@[:space:]]+:[^/@[:space:]]+@",
}

FORBIDDEN_PAYLOAD_FIELDS = {
    "value", "secret", "match", "line", "content", "excerpt", "password",
    "token", "key_material", "raw", "diff", "patch",
}


def git(
    repository: pathlib.Path,
    *args: str,
    text: bool = True,
    accepted_returncodes: tuple[int, ...] = (0,),
) -> str | bytes:
    completed = subprocess.run(
        ["git", "-c", f"safe.directory={repository.as_posix()}", "-C", str(repository), *args],
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        text=text,
    )
